<?php
use CmuLms\View;
$table=$student_activity??\CmuLms\Course::studentActivity((int)$course['id'],$_GET);
$tableQuery=['route'=>'course','id'=>(int)$course['id'],'tab'=>'students','students_search'=>$table['search'],'students_status'=>$table['status'],'students_per_page'=>$table['per_page'],'students_sort'=>$table['sort'],'students_direction'=>$table['direction']];
$tableLink=static fn(array $changes):string=>'?'.http_build_query(array_merge($tableQuery,$changes)).'#students-activity';
$dateLabel=static fn($date):string=>$date?date('M j, Y · g:i A',strtotime($date)):'Never';
?>
<section class="card student-activity-table" id="students-activity">
<div class="student-table-heading"><div><h2>Students and activity</h2><p class="muted">Enrollment, account access, and recent sign-in activity.</p></div><span class="badge"><?=(int)$table['total']?> students</span></div>
<form method="get" action="#students-activity" class="student-table-toolbar">
<input type="hidden" name="route" value="course"><input type="hidden" name="id" value="<?=(int)$course['id']?>"><input type="hidden" name="tab" value="students"><input type="hidden" name="students_sort" value="<?=View::e($table['sort'])?>"><input type="hidden" name="students_direction" value="<?=View::e($table['direction'])?>">
<label class="student-table-search">Search students<input type="search" name="students_search" value="<?=View::e($table['search'])?>" placeholder="Name, school ID, or section"></label>
<label>Status<select name="students_status"><?php foreach(['all'=>'All students','enabled'=>'Enabled accounts','disabled'=>'Disabled accounts','online'=>'Online','offline'=>'Offline'] as $value=>$label): ?><option value="<?=$value?>" <?=$table['status']===$value?'selected':''?>><?=$label?></option><?php endforeach; ?></select></label>
<label>Rows per page<select name="students_per_page"><?php foreach([10,20,50,100] as $per): ?><option value="<?=$per?>" <?=$table['per_page']===$per?'selected':''?>><?=$per?></option><?php endforeach; ?></select></label>
<button type="submit">Apply</button><a class="student-table-reset" href="?route=course&amp;id=<?=(int)$course['id']?>&amp;tab=students#students-activity">Reset</a>
</form>
<div class="student-table-scroll" role="region" aria-label="Student activity records" tabindex="0">
<table><thead><tr>
<?php foreach(['name'=>'Student','id_number'=>'School ID','section'=>'Section'] as $key=>$label): $sorted=$table['sort']===$key; ?><th scope="col" aria-sort="<?=$sorted?($table['direction']==='asc'?'ascending':'descending'):'none'?>"><a href="<?=View::e($tableLink(['students_sort'=>$key,'students_direction'=>$sorted&&$table['direction']==='asc'?'desc':'asc','students_page'=>1]))?>"><?=$label?> <span aria-hidden="true"><?=$sorted?($table['direction']==='asc'?'↑':'↓'):'↕'?></span></a></th><?php endforeach; ?>
<th scope="col">Account</th><th scope="col">Activity</th>
<?php foreach(['last_login'=>'Last login','last_logout'=>'Last logout'] as $key=>$label): $sorted=$table['sort']===$key; ?><th scope="col" aria-sort="<?=$sorted?($table['direction']==='asc'?'ascending':'descending'):'none'?>"><a href="<?=View::e($tableLink(['students_sort'=>$key,'students_direction'=>$sorted&&$table['direction']==='asc'?'desc':'asc','students_page'=>1]))?>"><?=$label?> <span aria-hidden="true"><?=$sorted?($table['direction']==='asc'?'↑':'↓'):'↕'?></span></a></th><?php endforeach; ?>
<th scope="col">Action</th></tr></thead><tbody>
<?php foreach($table['rows'] as $student): $disabled=!empty($student['disabled_at']);$action=$disabled?'Enable':'Disable';$confirmation=$action.' '.$student['name'].' (School ID: '.$student['id_number'].')?'; ?>
<tr><td class="student-name-cell"><?=View::e($student['name'])?></td><td><?=View::e($student['id_number'])?></td><td><?=View::e($student['section_code']??'—')?></td><td><span class="student-account-badge <?=$disabled?'is-disabled':'is-enabled'?>"><?=$disabled?'Disabled':'Enabled'?></span></td><td><span class="student-online-badge <?=$student['is_online']?'is-online':''?>"><?=$student['is_online']?'Online':'Offline'?></span></td><td class="student-date-cell"><?=View::e($dateLabel($student['last_login_at']))?></td><td class="student-date-cell"><?=View::e($dateLabel($student['last_logout_at']))?></td><td><form method="post" action="?route=admin-toggle" onsubmit="return confirm(<?=View::e(json_encode($confirmation))?>)"><?=View::csrfField()?><input type="hidden" name="course_id" value="<?=(int)$course['id']?>"><input type="hidden" name="user_id" value="<?=(int)$student['id']?>"><input type="hidden" name="state" value="<?=$disabled?'enable':'disable'?>"><button type="submit" class="student-account-action <?=$disabled?'enable-action':'disable-action'?>"><?=$action?></button></form></td></tr>
<?php endforeach; ?>
<?php if(!$table['rows']): ?><tr><td colspan="8" class="student-table-empty">No students match these filters.</td></tr><?php endif; ?>
</tbody></table></div>
<div class="student-table-footer"><span class="muted">Showing <?=$table['total']?($table['page']-1)*$table['per_page']+1:0?>–<?=min($table['page']*$table['per_page'],$table['total'])?> of <?=(int)$table['total']?> students</span><nav aria-label="Student table pagination">
<?php if($table['page']>1): ?><a href="<?=View::e($tableLink(['students_page'=>$table['page']-1]))?>">Previous</a><?php else: ?><span aria-disabled="true">Previous</span><?php endif; ?>
<?php for($page=max(1,$table['page']-2);$page<=min($table['pages'],$table['page']+2);$page++): ?><a <?=$page===$table['page']?'aria-current="page"':''?> href="<?=View::e($tableLink(['students_page'=>$page]))?>"><?=$page?></a><?php endfor; ?>
<?php if($table['page']<$table['pages']): ?><a href="<?=View::e($tableLink(['students_page'=>$table['page']+1]))?>">Next</a><?php else: ?><span aria-disabled="true">Next</span><?php endif; ?>
</nav></div>
</section>
<style>
#students-activity{scroll-margin-top:88px}.student-table-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.student-table-heading h2{margin:0 0 6px}.student-table-heading p{margin:0;font-size:13px}.student-table-toolbar{display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:18px}.student-table-toolbar label{display:grid;gap:6px;font-size:12px;font-weight:600}.student-table-search{flex:1;min-width:210px}.student-table-toolbar input,.student-table-toolbar select{font-size:14px;height:40px;padding:8px 10px}.student-table-toolbar button{margin:0;min-height:40px;align-self:flex-end}.student-table-reset{padding:10px 0;color:var(--green);font-size:13px}.student-table-scroll{overflow-x:auto;border:1px solid var(--line);border-radius:10px}.student-table-scroll table{font-size:13px;min-width:860px;display:table;white-space:normal}.student-table-scroll thead{background:#edf4ef}.student-table-scroll th{font-size:12px;padding:12px;white-space:nowrap}.student-table-scroll th a{color:var(--ink);text-decoration:none}.student-table-scroll th a:hover{text-decoration:underline}.student-table-scroll th a span{color:#6d8479;margin-left:4px}.student-table-scroll td{padding:12px;vertical-align:middle}.student-table-scroll tbody tr:nth-child(even){background:#fafcfb}.student-table-scroll tbody tr:hover{background:#f0f7f2}.student-table-scroll tbody tr:last-child td{border-bottom:0}.student-name-cell{font-weight:600;min-width:170px}.student-date-cell{font-size:12px;color:#65776d;min-width:135px}.student-account-badge,.student-online-badge{display:inline-flex;padding:4px 8px;border-radius:6px;font-size:11px;white-space:nowrap}.student-account-badge.is-enabled{background:#e5f3e9;color:#24664d}.student-account-badge.is-disabled{background:#fdebea;color:#a3342b}.student-online-badge{background:#edf0f2;color:#5d6b75}.student-online-badge.is-online{background:#def6e8;color:#126742}.student-table-scroll .student-account-action{min-height:32px;width:auto;padding:7px 10px;font:600 12px Arial,sans-serif}.student-table-scroll .disable-action{background:#fff;color:#9b3e32;border:1px solid #e0c4be}.student-table-scroll .enable-action{background:var(--green);color:#fff}.student-table-empty{text-align:center!important;padding:30px!important;color:#65776d}.student-table-footer{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;margin-top:16px;font-size:12px}.student-table-footer nav{display:flex;align-items:center;gap:5px;flex-wrap:wrap}.student-table-footer nav a,.student-table-footer nav span{padding:8px 10px;border:1px solid var(--line);border-radius:6px;text-decoration:none;color:var(--ink);background:#fff}.student-table-footer nav [aria-current]{background:var(--green);color:#fff;border-color:var(--green)}.student-table-footer nav [aria-disabled]{opacity:.5;cursor:not-allowed}@media(max-width:600px){.student-table-heading{align-items:flex-start}.student-table-toolbar label{flex:1;min-width:125px}.student-table-toolbar .student-table-search{flex-basis:100%}.student-table-footer{align-items:flex-start;flex-direction:column}}
.student-activity-table .student-table-toolbar button{align-self:flex-end}
</style>
